CREATE TABLE t5 (val int, period text PRIMARY KEY); INSERT INTO t5 VALUES(5,'2001-3'),(10,'2001-4'),(15,'2002-1'),(5,'2002-2'),(10,'2002-3'),(15,'2002-4'),(10,'2003-1'),(5,'2003-2'),(25,'2003-3'),(5,'2003-4'); INSERT INTO _result(period,vsum) SELECT period, vsum FROM (SELECT a.period, (SELECT sum(val) FROM t5 WHERE period BETWEEN a.period AND '2002-4') vsum FROM t5 a WHERE a.period BETWEEN '2002-1' AND '2002-4') WHERE vsum < 45;